7	INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	See LICENSE in the root of the software repository for the full text of the License.
9	*/
10	
11	// GEMM Compute Kernel (Cube Arch)
12	//
13	// Computes C_local = A_local * B for all output tiles, then signals
14	// the communication kernel via per-block ready queues.
15	//
16	// Two-level double-buffered pipeline:
17	//   L1 (MTE2):  TLOAD every stepK iterations (4x DMA reduction)
18	//   L0 (MTE1):  TEXTRACT individual K-slices from cached L1 panel
19	//   Cube (M):   TMATMUL / TMATMUL_ACC accumulation
20	
21	#ifndef PIPE_FIX
22	#define PIPE_FIX static_cast<pipe_t>(10)
23	#endif
24	
25	#include <pto/common/constants.hpp>
26	#include <pto/pto-inst.hpp>
27	#include "ready_queue.hpp"
28	#include "gemm_ar_config.h"
29	#include "kernel_launchers.h"
30	
31	using namespace pto;
32	
33	// ============================================================================
34	// ProcessKIteration: K-loop with L1 caching (stepK=4)
35	// Every stepKa iterations, loads a larger panel into L1 for reuse,
36	// reducing GM→L1 DMA frequency by 4x.
37	// ============================================================================
38	template <
39	    typename T, typename U, typename S, int M, int K, int N, uint32_t baseM, uint32_t baseK, uint32_t baseN,
40	    uint32_t stepKa, uint32_t stepKb>
41	AICORE inline void ProcessKIteration(
42	    uint32_t kIter, __gm__ U* currentSrc0, __gm__ S* currentSrc1,
43	    Tile<TileType::Mat, U, baseM, baseK * stepKa, BLayout::ColMajor, baseM, baseK * stepKa, SLayout::RowMajor>
44	        aMatTile[2],
45	    Tile<TileType::Mat, S, baseK * stepKb, baseN, BLayout::RowMajor, baseK * stepKb, baseN, SLayout::ColMajor>
46	        bMatTile[2],
47	    TileLeft<U, baseM, baseK, baseM, baseK> aTile[2], TileRight<S, baseK, baseN, baseK, baseN> bTile[2],
48	    TileAcc<T, baseM, baseN, baseM, baseN>& cTile, uint8_t& mte2DBFlag, uint8_t& mte1DBFlag, uint32_t k_stride)
49	{
50	    using NDValidShapeA = TileShape2D<U, baseM, baseK * stepKa, Layout::ND>;
51	    using NDsingleCoreShapeA = BaseShape2D<U, M, DYNAMIC, Layout::ND>;
52	    using GlobalDataSrcA = GlobalTensor<U, NDValidShapeA, NDsingleCoreShapeA, Layout::ND>;
53	
54	    using NDValidShapeB = TileShape2D<U, baseK * stepKb, baseN, Layout::DN>;
55	    using NDsingleCoreShapeB = BaseShape2D<U, DYNAMIC, N, Layout::DN>;
56	    using GlobalDataSrcB = GlobalTensor<U, NDValidShapeB, NDsingleCoreShapeB, Layout::DN>;
57	
58	    const uint32_t kModStepKa = kIter % stepKa;
59	
60	    // TLOAD: every stepKa iterations, load larger panel into L1
61	    if (kModStepKa == 0) {
62	        NDsingleCoreShapeA aStride(M, k_stride);
63	        NDsingleCoreShapeB bStride(k_stride, N);
64	        NDValidShapeA aShape;
65	        NDValidShapeB bShape;
66	        GlobalDataSrcA gmA(currentSrc0 + kIter * baseK, aShape, aStride);
67	        GlobalDataSrcB gmB(currentSrc1 + kIter * baseK, bShape, bStride);
68	
69	        wait_flag(PIPE_MTE1, PIPE_MTE2, (event_t)mte2DBFlag);
70	        TLOAD(aMatTile[mte2DBFlag], gmA);
71	        set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
72	        TLOAD(bMatTile[mte2DBFlag], gmB);
73	        set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID1);
74	        mte2DBFlag = (mte2DBFlag == 0) ? 1 : 0;
75	    }
76	
77	    const uint32_t currMte2Idx = (mte2DBFlag == 0) ? 1 : 0;
78	
79	    // TEXTRACT: extract current K-slice from cached L1 panel
80	    wait_flag(PIPE_M, PIPE_MTE1, (event_t)mte1DBFlag);
81	
82	    if (kModStepKa == 0)
83	        wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
84	    TEXTRACT(aTile[mte1DBFlag], aMatTile[currMte2Idx], 0, kModStepKa * baseK);
85	
86	    if (kModStepKa == 0)
87	        wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID1);
88	    TEXTRACT(bTile[mte1DBFlag], bMatTile[currMte2Idx], (kIter % stepKb) * baseK, 0);
89	
90	    if ((kIter + 1) % stepKa == 0) {
91	        set_flag(PIPE_MTE1, PIPE_MTE2, (event_t)currMte2Idx);
92	    }
93	
94	    // TMATMUL
95	    set_flag(PIPE_MTE1, PIPE_M, (event_t)mte1DBFlag);
96	    wait_flag(PIPE_MTE1, PIPE_M, (event_t)mte1DBFlag);
97	    if (kIter == 0) {
98	        TMATMUL(cTile, aTile[mte1DBFlag], bTile[mte1DBFlag]);
99	    } else {
100	        TMATMUL_ACC(cTile, cTile, aTile[mte1DBFlag], bTile[mte1DBFlag]);
101	    }
102	    set_flag(PIPE_M, PIPE_MTE1, (event_t)mte1DBFlag);
103	    mte1DBFlag = (mte1DBFlag == 0) ? 1 : 0;
104	}
105	
106	// ============================================================================
107	// Global GEMM parameters (shared across kernel and host code)
108	// ============================================================================
109	
110	constexpr uint32_t G_K_LOOP = G_K / G_BASE_K;
111	
112	// L1 caching: load stepK K-slices per TLOAD
113	// L1 usage: 2×64KB(A) + 2×128KB(B) = 384KB ≤ 1024KB L1 capacity
114	constexpr uint32_t G_STEP_KA = 4;
115	constexpr uint32_t G_STEP_KB = 4;
116	static_assert(G_K_LOOP % G_STEP_KA == 0, "G_K_LOOP must be divisible by G_STEP_KA");
117	static_assert(G_K_LOOP % G_STEP_KB == 0, "G_K_LOOP must be divisible by G_STEP_KB");
118	static_assert(G_STEP_KA == G_STEP_KB, "Current implementation assumes stepKa == stepKb");
119	static_assert(G_K_LOOP >= G_STEP_KA, "K_LOOP must be >= stepKa for L1 caching");
120	
121	// ============================================================================
122	// Type aliases for compute kernel tiles
123	// ============================================================================
124	using TileMatAData = Tile<
125	    TileType::Mat, half, G_BASE_M, G_BASE_K * G_STEP_KA, BLayout::ColMajor, G_BASE_M, G_BASE_K * G_STEP_KA,
126	    SLayout::RowMajor>;
127	using TileMatBData = Tile<
128	    TileType::Mat, half, G_BASE_K * G_STEP_KB, G_BASE_N, BLayout::RowMajor, G_BASE_K * G_STEP_KB, G_BASE_N,
129	    SLayout::ColMajor>;
130	using LeftTileT = TileLeft<half, G_BASE_M, G_BASE_K, G_BASE_M, G_BASE_K>;
131	using RightTileT = TileRight<half, G_BASE_K, G_BASE_N, G_BASE_K, G_BASE_N>;
132	using ResTileT = TileAcc<float, G_BASE_M, G_BASE_N, G_BASE_M, G_BASE_N>;
133	
134	// Swizzle: remap linear index to column-major within N_TILES-wide groups
135	// to improve B-matrix L1 reuse (consecutive tiles share the same N column).
136	AICORE inline void SwizzleTileIndex(int linear_idx, uint32_t& mi, uint32_t& ni)
137	{
138	    constexpr uint32_t SWIZZLE_GROUP = G_N_TILES;
139	    uint32_t group = linear_idx / SWIZZLE_GROUP;
140	    uint32_t local = linear_idx % SWIZZLE_GROUP;
141	    mi = group;
142	    ni = (group & 1) ? (SWIZZLE_GROUP - 1 - local) : local;
143	    if (mi >= G_M_TILES) {
144	        mi = linear_idx / G_N_TILES;
145	        ni = linear_idx % G_N_TILES;
146	    }
147	}
148	
149	// Run the K-loop for one output tile, then store result to GM and signal comm kernel.
150	AICORE inline void ComputeAndStoreTile(
151	    __gm__ half* gemm_output, __gm__ half* src0, __gm__ half* src1, volatile __gm__ PerBlockQueue* my_queue,
152	    TileMatAData aMatTile[2], TileMatBData bMatTile[2], LeftTileT aTile[2], RightTileT bTile[2], ResTileT& cTile,
153	    uint32_t mi, uint32_t ni, uint32_t k_per_rank, int32_t& enqueue_slot)
154	{
155	    using NDValidShapeC = TileShape2D<half, G_BASE_M, G_BASE_N>;
156	    using NDWholeShapeC = BaseShape2D<half, G_M, G_N>;
157	    using GlobalDataOut = GlobalTensor<half, NDValidShapeC, NDWholeShapeC>;
158	
159	    __gm__ half* currentSrc0 = src0 + mi * G_BASE_M * k_per_rank;
160	    __gm__ half* currentSrc1 = src1 + ni * G_BASE_N * k_per_rank;
161	
162	    uint8_t mte2DBFlag = 0, mte1DBFlag = 0;
163	    uint32_t k_loop_per_rank = k_per_rank / G_BASE_K;
164	    static_assert(G_BASE_K == 64, "G_BASE_K must be 64 for this implementation");
165	
166	    set_flag(PIPE_MTE1, PIPE_MTE2, EVENT_ID0);
167	    set_flag(PIPE_MTE1, PIPE_MTE2, EVENT_ID1);
168	    set_flag(PIPE_M, PIPE_MTE1, EVENT_ID0);
169	    set_flag(PIPE_M, PIPE_MTE1, EVENT_ID1);
170	
171	    for (uint32_t kIter = 0; kIter < k_loop_per_rank; kIter++) {
172	        ProcessKIteration<float, half, half, G_M, G_K, G_N, G_BASE_M, G_BASE_K, G_BASE_N, G_STEP_KA, G_STEP_KB>(
173	            kIter, currentSrc0, currentSrc1, aMatTile, bMatTile, aTile, bTile, cTile, mte2DBFlag, mte1DBFlag,
174	            k_per_rank);
175	    }
176	
177	    wait_flag(PIPE_MTE1, PIPE_MTE2, EVENT_ID0);
178	    wait_flag(PIPE_MTE1, PIPE_MTE2, EVENT_ID1);
179	    wait_flag(PIPE_M, PIPE_MTE1, EVENT_ID0);
180	    wait_flag(PIPE_M, PIPE_MTE1, EVENT_ID1);
181	
182	    uint64_t outOffset = (uint64_t)(mi * G_BASE_M) * G_N + ni * G_BASE_N;
183	    GlobalDataOut dstGlobal(gemm_output + outOffset);
184	
185	    set_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
186	    wait_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
187	    TSTORE(dstGlobal, cTile);
188	
189	    pipe_barrier(PIPE_ALL);
190	
191	    int tile_idx = mi * G_N_TILES + ni;
192	    MultiBlockEnqueueFast(my_queue, tile_idx, enqueue_slot);
193	    enqueue_slot++;
194	}
195	
196	// ============================================================================
197	// GemmComputeImpl: Core compute logic
198	//
199	// Each block handles a subset of tiles (no contention — sole producer per queue).
200	// ============================================================================
201	AICORE inline void GemmComputeImpl(
202	    __gm__ half* gemm_output, __gm__ half* src0, __gm__ half* src1, __gm__ MultiBlockQueueSet* queue_set, int rank,
203	    int launch_block_count, uint32_t k_per_rank)
204	{
205	    const int core_idx = get_block_idx();
206	
207	    TileMatAData aMatTile[2];
208	    TileMatBData bMatTile[2];
209	    constexpr size_t l1ASize = G_BASE_M * G_BASE_K * G_STEP_KA * sizeof(half);
210	    constexpr size_t l1BSize = G_BASE_K * G_STEP_KB * G_BASE_N * sizeof(half);
211	    TASSIGN(aMatTile[0], 0x0);
212	    TASSIGN(aMatTile[1], 0x0 + l1ASize);
213	    TASSIGN(bMatTile[0], 0x0 + 2 * l1ASize);
214	    TASSIGN(bMatTile[1], 0x0 + 2 * l1ASize + l1BSize);
215	
216	    LeftTileT aTile[2];
217	    RightTileT bTile[2];
218	    ResTileT cTile;
219	    TASSIGN(aTile[0], 0x0);
220	    TASSIGN(aTile[1], 0x0 + G_BASE_M * G_BASE_K * sizeof(half));
221	    TASSIGN(bTile[0], 0x0);
222	    TASSIGN(bTile[1], 0x0 + G_BASE_K * G_BASE_N * sizeof(half));
223	    TASSIGN(cTile, 0x0);
224	
225	    const int total_tiles = G_NUM_TILES;
226	    const int my_start_tile = GEMM_AR_BLOCK_START_TILE(core_idx, total_tiles, launch_block_count);
227	    const int my_end_tile = my_start_tile + GEMM_AR_BLOCK_TILE_COUNT(core_idx, total_tiles, launch_block_count);
228	
229	    volatile __gm__ PerBlockQueue* my_queue = GetMyBlockQueue((volatile __gm__ MultiBlockQueueSet*)queue_set, core_idx);
230	    int32_t enqueue_slot = 0;
231	
232	    for (int linear_idx = my_start_tile; linear_idx < my_end_tile && linear_idx < total_tiles; linear_idx++) {
233	        uint32_t mi, ni;
234	        SwizzleTileIndex(linear_idx, mi, ni);
235	        ComputeAndStoreTile(
236	            gemm_output, src0, src1, my_queue, aMatTile, bMatTile, aTile, bTile, cTile, mi, ni, k_per_rank,
237	            enqueue_slot);
238	    }
239	}
240	
241	// ============================================================================
242	// Kernel entry point and host-side launcher
243	// ============================================================================
244	__global__ AICORE void GemmComputeKernel(
245	    __gm__ uint8_t* gemm_output, __gm__ uint8_t* src0, __gm__ uint8_t* src1, __gm__ uint8_t* queue_set, int rank,
246	    int launch_block_count, uint32_t k_per_rank)
247	{
248	    GemmComputeImpl(
249	        reinterpret_cast<__gm__ half*>(gemm_output), reinterpret_cast<__gm__ half*>(src0),
250	        reinterpret_cast<__gm__ half*>(src1), reinterpret_cast<__gm__ MultiBlockQueueSet*>(queue_set), rank,
251	        launch_block_count, k_per_rank);
252	}
253	
254	void launchGemmCompute(
255	    uint8_t* gemm_output, uint8_t* src0, uint8_t* src1, uint8_t* queue_set, int rank, void* stream,
256	    int launch_block_count, uint32_t k_per_rank)
257	{
258	    GemmComputeKernel<<<launch_block_count, nullptr, stream>>>(
259	        gemm_output, src0, src1, queue_set, rank, launch_block_count, k_per_rank);
260	}
261

