10	
11	// Communication Kernel (Vec Arch) for GEMM + AllReduce — HCCL backend
12	//
13	// Overlapped RS/AG kernel.
14	// RS uses TPUT<AtomicAdd> to accumulate directly at the owner's reduced_output,
15	// then publishes owner-local ready counters so AG can drain completed subtiles
16	// without a device-wide RS→AG barrier.
17	//
18	// Signal matrix layout in HCCL window (per rank):
19	//   [0 .. MAX_RANKS-1]                Reserved legacy cross-rank barrier counters
20	//   [MAX_RANKS]                       Reserved legacy local broadcast flag slot
21	//   [MAX_RANKS + 1]                   Reserved legacy intra-rank arrival slot
22	//   [G_SIGNAL_SUBTILE_READY_OFFSET .. G_SIGNAL_AG_SUMMARY_OFFSET-1]
23	//                                     Owner-local subtile-ready counters
24	//   [G_SIGNAL_AG_SUMMARY_OFFSET .. G_SIGNAL_TOTAL_SLOTS-1]
25	//                                     Per-AG-block summary wakeup counters
26	
27	#ifndef PIPE_FIX
28	#define PIPE_FIX static_cast<pipe_t>(10)
29	#endif
30	
31	#include <cstddef>
32	#include <cstdint>
33	
34	#include "pto/comm/pto_comm_inst.hpp"
35	#include "pto/common/pto_tile.hpp"
36	#include <pto/pto-inst.hpp>
37	
38	#include "common.hpp"
39	#include "ready_queue.hpp"
40	
41	#include "gemm_ar_config.h"
42	#include "kernel_launchers.h"
43	
44	// Signal matrix layout (per rank, in HCCL RDMA window):
45	//   [0 .. G_SIGNAL_RS_DONE_SLOTS-1]             Reserved legacy cross-rank barrier counters
46	//   [G_SIGNAL_LOCAL_FLAG_OFFSET]                Reserved legacy local broadcast flag slot
47	//   [G_SIGNAL_INTRA_RANK_COUNTER_OFFSET]        Reserved legacy intra-rank arrival slot
48	//   [G_SIGNAL_SUBTILE_READY_OFFSET .. G_SIGNAL_AG_SUMMARY_OFFSET-1]
49	//                                              Owner-local subtile-ready counters
50	//   [G_SIGNAL_AG_SUMMARY_OFFSET .. G_SIGNAL_TOTAL_SLOTS-1]
51	//                                              Per-AG-block summary wakeup counters
52	
53	using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
54	using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
55	using Global = pto::GlobalTensor<half, ShapeDyn, StrideDyn, pto::Layout::ND>;
56	using RsSubtileData = pto::Tile<pto::TileType::Vec, half, G_COMM_SUB_M, G_BASE_N, pto::BLayout::RowMajor, -1, -1>;
57	using AgSubtileData = RsSubtileData;
58	
59	static constexpr size_t RS_SUBTILE_UB_BYTES = ((G_COMM_SUB_M * G_BASE_N * sizeof(half) + 1023) / 1024) * 1024;
60	static constexpr size_t AG_SUBTILE_UB_OFFSET = RS_SUBTILE_UB_BYTES * 2;
61	
62	// ============================================================================
63	// RS helpers — broken out to reduce cyclomatic complexity
64	// ============================================================================
65	
66	struct RsPendingMeta {
67	    int owner;
68	    int local_subtile_id;
69	    int ag_summary_block;
70	};
71	
72	AICORE inline uint64_t RsSubtileRowOffset(int tile_idx, int stripe_id)
73	{
74	    const uint32_t mi = tile_idx / G_N_TILES;
75	    const uint32_t ni = tile_idx % G_N_TILES;
76	    const uint64_t tile_base = (uint64_t)(mi * G_BASE_M) * G_N + ni * G_BASE_N;
77	    return tile_base + (uint64_t)stripe_id * G_COMM_SUB_M * G_N;
78	}
79	
80	AICORE inline int RsOwnerLocalSubtileId(int tile_idx, int nranks, int stripe_id)
81	{
82	    const int safe_nranks = (nranks > 0) ? nranks : 1;
83	    const int owner_local_tile = tile_idx / safe_nranks;
84	    return owner_local_tile * static_cast<int>(G_COMM_SUBTILES_PER_TILE) + stripe_id;
85	}
86	
87	// Subtile -> owning comm block mapping.
88	// Reversed-stripe layout: subtile k goes to block (num_comm_blocks-1-k%num_comm_blocks).
89	// Rationale: combined with A's rsN balancing (blocks 0..remainder-1 get the
90	// heavier rsN=ceil and blocks remainder.. get the lighter rsN=floor), reversing
91	// AG makes AG's "heavy" blocks (agN=ceil) land on RS's "light" blocks, so the
92	// total (rsN+agN) workload is flatter. Must stay consistent with
93	// AgInitAssignedState starting index.
94	AICORE inline int AgSummaryBlockForSubtile(int local_subtile_id, int num_comm_blocks)
95	{
96	    return (num_comm_blocks > 0) ? (num_comm_blocks - 1 - (local_subtile_id % num_comm_blocks)) : 0;
97	}
98	
99	AICORE inline __gm__ int32_t* AgSummarySlotPtr(__gm__ int32_t* signal_base, int summary_block)
100	{
101	    return signal_base + G_SIGNAL_AG_SUMMARY_OFFSET + summary_block * G_SIGNAL_AG_SUMMARY_STRIDE;
102	}
103	
104	AICORE inline void RsNotifySubtileReady(
105	    __gm__ CommDeviceContext* hcclCtx, __gm__ int32_t* signal_base, int my_rank, const RsPendingMeta& meta)
106	{
107	    __gm__ int32_t* counter = signal_base + G_SIGNAL_SUBTILE_READY_OFFSET + meta.local_subtile_id;
108	    if (meta.owner != my_rank) {
109	        counter = CommRemotePtr(hcclCtx, counter, meta.owner);
110	    }
111	    pto::comm::Signal sig(counter);
112	    pto::comm::TNOTIFY(sig, static_cast<int32_t>(1), pto::comm::NotifyOp::AtomicAdd);
113	}
114	
115	AICORE inline void RsNotifyAgSummary(
116	    __gm__ CommDeviceContext* hcclCtx, __gm__ int32_t* signal_base, int my_rank, const RsPendingMeta& meta)
117	{
118	    __gm__ int32_t* counter = AgSummarySlotPtr(signal_base, meta.ag_summary_block);
119	    if (meta.owner != my_rank) {
120	        counter = CommRemotePtr(hcclCtx, counter, meta.owner);
121	    }
122	    pto::comm::Signal sig(counter);
123	    pto::comm::TNOTIFY(sig, static_cast<int32_t>(1), pto::comm::NotifyOp::AtomicAdd);
124	}
125	
126	AICORE inline void RsPublishSubtileReady(
127	    __gm__ CommDeviceContext* hcclCtx, __gm__ int32_t* signal_base, int my_rank, const RsPendingMeta& meta)
128	{
129	    // Match the proven allgather_gemm protocol: flush local pipeline state and
130	    // commit DDR visibility before publishing the doorbell for this subtile.
131	    pipe_barrier(PIPE_ALL);
132	    dsb(DSB_DDR);
133	    RsNotifySubtileReady(hcclCtx, signal_base, my_rank, meta);
134	    RsNotifyAgSummary(hcclCtx, signal_base, my_rank, meta);
135	}
136	
137	// Round-robin poll across assigned queues; returns tile index or -1.
138	AICORE inline int32_t RsPollQueues(
139	    volatile __gm__ MultiBlockQueueSet* qset, const int* my_queue_indices, int my_queue_count, int32_t* heads,
140	    const int32_t* queue_max_tiles, int& next_queue_offset)
141	{
142	    if (my_queue_count <= 0) {
143	        return -1;
144	    }
145	    for (int i = 0; i < my_queue_count; i++) {
146	        int local_idx = (next_queue_offset + i) % my_queue_count;
147	        int32_t q = my_queue_indices[local_idx];
148	
149	        if (heads[q] >= queue_max_tiles[q])
150	            continue;
151	
152	        volatile __gm__ PerBlockQueue* pq = GetMyBlockQueue(qset, q);
153	        int32_t tile = PerBlockQueueTryDequeue(pq, heads[q]);
154	
155	        if (tile >= 0) {
156	            heads[q]++;
157	            next_queue_offset = (local_idx + 1) % my_queue_count;
158	            return tile;
159	        }
160	    }
161	    return -1;
162	}
163	
164	// Ping-pong pipeline: load current tile, optionally store previous tile.
165	AICORE inline void RsPipelineStep(
166	    RsSubtileData& pingTile, RsSubtileData& pongTile, Global& pp_pending_dst, RsPendingMeta& pp_pending_meta,
167	    Global& dstG, const RsPendingMeta& curMeta, Global& srcG, int pp_count, __gm__ CommDeviceContext* hcclCtx,
168	    __gm__ int32_t* signal_base, int my_rank)
169	{
170	    bool use_ping = (pp_count % 2 == 0);
171	    RsSubtileData& curTile = use_ping ? pingTile : pongTile;
172	    event_t curEv = use_ping ? EVENT_ID0 : EVENT_ID1;
173	
174	    if (pp_count == 0) {
175	        TLOAD(curTile, srcG);
176	        set_flag(PIPE_MTE2, PIPE_MTE3, curEv);
177	    } else {
178	        RsSubtileData& prevTile = use_ping ? pongTile : pingTile;
179	        event_t prevEv = use_ping ? EVENT_ID1 : EVENT_ID0;
180	
181	        wait_flag(PIPE_MTE2, PIPE_MTE3, prevEv);
182	        TSTORE_IMPL<RsSubtileData, Global, pto::AtomicType::AtomicAdd>(pp_pending_dst, prevTile);
183	        TLOAD(curTile, srcG);
184	        set_flag(PIPE_MTE3, PIPE_MTE2, prevEv);
185	        set_flag(PIPE_MTE2, PIPE_MTE3, curEv);
186	        wait_flag(PIPE_MTE3, PIPE_MTE2, prevEv);
187	        RsPublishSubtileReady(hcclCtx, signal_base, my_rank, pp_pending_meta);
188	    }
189	
190	    pp_pending_dst = dstG;
191	    pp_pending_meta = curMeta;
192	}
193	
194	// Drain the last tile still in the pipeline after the RS loop.
195	AICORE inline void RsFlushPipeline(
196	    RsSubtileData& pingTile, RsSubtileData& pongTile, Global& pp_pending_dst, const RsPendingMeta& pp_pending_meta,
197	    int pp_count, __gm__ CommDeviceContext* hcclCtx, __gm__ int32_t* signal_base, int my_rank)
198	{
199	    if (pp_count <= 0)
200	        return;
201	
202	    bool last_was_ping = ((pp_count - 1) % 2 == 0);
203	    RsSubtileData& lastTile = last_was_ping ? pingTile : pongTile;
204	    event_t lastEv = last_was_ping ? EVENT_ID0 : EVENT_ID1;
205	    wait_flag(PIPE_MTE2, PIPE_MTE3, lastEv);
206	    TSTORE_IMPL<RsSubtileData, Global, pto::AtomicType::AtomicAdd>(pp_pending_dst, lastTile);
207	    set_flag(PIPE_MTE3, PIPE_MTE2, lastEv);
208	    wait_flag(PIPE_MTE3, PIPE_MTE2, lastEv);
209	    RsPublishSubtileReady(hcclCtx, signal_base, my_rank, pp_pending_meta);
210	}
211	
212	AICORE inline void RsProcessTileStripes(
213	    __gm__ half* gemm_output, __gm__ half* reduced_output, __gm__ int32_t* signal_base,
214	    __gm__ CommDeviceContext* hcclCtx, int my_rank, int safe_nranks, int32_t tile_idx, const ShapeDyn& subtileShape,
215	    const StrideDyn& subtileStride, RsSubtileData& pingTile, RsSubtileData& pongTile, Global& pp_pending_dst,
216	    RsPendingMeta& pp_pending_meta, int& pp_count, int num_comm_blocks)
217	{
218	    const int owner = tile_idx % safe_nranks;
219	    for (int stripe_id = 0; stripe_id < static_cast<int>(G_COMM_SUBTILES_PER_TILE); ++stripe_id) {
220	        const uint64_t row_offset = RsSubtileRowOffset(tile_idx, stripe_id);
221	        const int local_subtile_id = RsOwnerLocalSubtileId(tile_idx, safe_nranks, stripe_id);
222	        const int ag_summary_block = AgSummaryBlockForSubtile(local_subtile_id, num_comm_blocks);
223	        Global srcG(gemm_output + row_offset, subtileShape, subtileStride);
224	
225	        __gm__ half* dst_ptr = (owner == my_rank) ? reduced_output + row_offset :
226	                                                    CommRemotePtr(hcclCtx, reduced_output, owner) + row_offset;
227	        Global dstG(dst_ptr, subtileShape, subtileStride);
228	
229	        RsPendingMeta curMeta{owner, local_subtile_id, ag_summary_block};
230	        RsPipelineStep(
231	            pingTile, pongTile, pp_pending_dst, pp_pending_meta, dstG, curMeta, srcG, pp_count, hcclCtx, signal_base,
232	            my_rank);
233	        pp_count++;
234	    }
235	}
236	
237	// Block on the first non-exhausted queue via TWAIT.
238	AICORE inline void RsWaitOnQueue(
239	    volatile __gm__ MultiBlockQueueSet* qset, const int* my_queue_indices, int my_queue_count, const int32_t* heads,
240	    const int32_t* queue_max_tiles, int next_queue_offset)
241	{
242	    if (my_queue_count <= 0) {
243	        return;
244	    }
245	    for (int i = 0; i < my_queue_count; i++) {
246	        int local_idx = (next_queue_offset + i) % my_queue_count;
247	        int32_t q = my_queue_indices[local_idx];
248	        if (heads[q] < queue_max_tiles[q]) {
249	            volatile __gm__ PerBlockQueue* pq = GetMyBlockQueue(qset, q);
250	            pto::comm::Signal sig(const_cast<__gm__ int32_t*>(&pq->count));
251	            pto::comm::TWAIT(sig, heads[q] + 1, pto::comm::WaitCmp::GE);
252	            return;
253	        }
254	    }
255	}
256	
257	// Build the per-block queue assignment and tile counts for this RS block.
258	// Returns total expected tiles; writes my_queue_count via out-param.
259	AICORE inline int RsInitQueueState(
260	    int comm_block_idx, int num_compute_blocks, int num_comm_blocks, int* my_queue_indices, int& my_queue_count,
261	    int32_t* queue_max_tiles)
262	{
263	    my_queue_count = 0;
264	    if (num_compute_blocks <= 0 || num_comm_blocks <= 0) {
265	        return 0;
266	    }
267	    if (comm_block_idx < 0 || comm_block_idx >= num_comm_blocks) {
268	        return 0;
269	    }
270	
271	    for (int q = comm_block_idx; q < num_compute_blocks; q += num_comm_blocks) {
272	        my_queue_indices[my_queue_count++] = q;
273	    }
274	
275	    const int total_tiles = G_NUM_TILES;
276	
277	    int my_expected_tiles = 0;
278	    for (int i = 0; i < my_queue_count; i++) {
279	        int q = my_queue_indices[i];
280	        int block_tiles = GEMM_AR_BLOCK_TILE_COUNT(q, total_tiles, num_compute_blocks);
281	        queue_max_tiles[q] = block_tiles;
282	        my_expected_tiles += block_tiles;
283	    }
284	    return my_expected_tiles;
285	}
286	
287	AICORE inline bool RsTryProcessOneTile(
288	    __gm__ half* gemm_output, __gm__ half* reduced_output, __gm__ int32_t* signal_base,
289	    volatile __gm__ MultiBlockQueueSet* qset, __gm__ CommDeviceContext* hcclCtx, int my_rank, int nranks,
290	    const ShapeDyn& subtileShape, const StrideDyn& subtileStride, RsSubtileData& pingTile, RsSubtileData& pongTile,
291	    Global& pp_pending_dst, RsPendingMeta& pp_pending_meta, const int* my_queue_indices, int my_queue_count,
292	    int32_t* heads, const int32_t* queue_max_tiles, int& next_queue_offset, int& pp_count, int32_t& tiles_sent,
293	    int32_t my_expected_tiles, int num_comm_blocks)
294	{
295	    if (tiles_sent >= my_expected_tiles) {
296	        return false;
297	    }
298	
299	    int32_t tile_idx = RsPollQueues(qset, my_queue_indices, my_queue_count, heads, queue_max_tiles, next_queue_offset);
300	    if (tile_idx < 0) {
301	        return false;
302	    }
303	
304	    const int safe_nranks = (nranks > 0) ? nranks : 1;
305	    RsProcessTileStripes(
306	        gemm_output, reduced_output, signal_base, hcclCtx, my_rank, safe_nranks, tile_idx, subtileShape, subtileStride,
307	        pingTile, pongTile, pp_pending_dst, pp_pending_meta, pp_count, num_comm_blocks);
308	
309	    tiles_sent++;
310	    if (tiles_sent >= my_expected_tiles) {
311	        RsFlushPipeline(pingTile, pongTile, pp_pending_dst, pp_pending_meta, pp_count, hcclCtx, signal_base, my_rank);
312	        pp_count = 0;
313	    }
314	    return true;
315	}
316	
317	// ============================================================================
318	// Phase 1: ReduceScatter — subtile TPUT with AtomicAdd to owner's reduced_output
319	//
320	// Only block 0..(num_compute_blocks-1) participate.
321	// Blocks >= num_compute_blocks skip straight to the barrier.
322	// ============================================================================
323	AICORE inline void ReduceScatterPhase(
324	    __gm__ half* gemm_output, __gm__ half* reduced_output, __gm__ int32_t* signal_base,
325	    __gm__ MultiBlockQueueSet* queue_set, __gm__ CommDeviceContext* hcclCtx, int my_rank, int nranks,
326	    int num_compute_blocks, int comm_block_idx, int num_comm_blocks)
327	{
328	    if (num_comm_blocks <= 0 || comm_block_idx >= num_comm_blocks)
329	        return;
330	
331	    volatile __gm__ MultiBlockQueueSet* qset = (volatile __gm__ MultiBlockQueueSet*)queue_set;
332	
333	    ShapeDyn subtileShape(1, 1, 1, G_COMM_SUB_M, G_BASE_N);
334	    StrideDyn subtileStride(G_BASE_M * G_N, G_BASE_M * G_N, G_BASE_M * G_N, G_N, 1);
335	
336	    RsSubtileData pingTile(G_COMM_SUB_M, G_BASE_N);
337	    RsSubtileData pongTile(G_COMM_SUB_M, G_BASE_N);
338	    TASSIGN(pingTile, 0x0);
339	    TASSIGN(pongTile, RS_SUBTILE_UB_BYTES);
340	
341	    int32_t heads[MAX_COMPUTE_BLOCKS];
342	    for (int b = 0; b < MAX_COMPUTE_BLOCKS; b++)
343	        heads[b] = 0;
344	
345	    int my_queue_indices[MAX_COMPUTE_BLOCKS];
346	    int32_t queue_max_tiles[MAX_COMPUTE_BLOCKS];
347	    int my_queue_count = 0;
348	    int my_expected_tiles = RsInitQueueState(
349	        comm_block_idx, num_compute_blocks, num_comm_blocks, my_queue_indices, my_queue_count, queue_max_tiles);
350	
351	    int next_queue_offset = 0;
352	    int pp_count = 0;
353	    int32_t tiles_sent = 0;
354	    Global pp_pending_dst(gemm_output, subtileShape, subtileStride);
355	    RsPendingMeta pp_pending_meta{0, 0, 0};
356	
357	    while (tiles_sent < my_expected_tiles) {
358	        int32_t tile_idx =
359	            RsPollQueues(qset, my_queue_indices, my_queue_count, heads, queue_max_tiles, next_queue_offset);
360	        if (tile_idx < 0) {
361	            RsWaitOnQueue(qset, my_queue_indices, my_queue_count, heads, queue_max_tiles, next_queue_offset);
362	            continue;
363	        }
364	
365	        const int safe_nranks = (nranks > 0) ? nranks : 1;
366	        RsProcessTileStripes(
367	            gemm_output, reduced_output, signal_base, hcclCtx, my_rank, safe_nranks, tile_idx, subtileShape,
368	            subtileStride, pingTile, pongTile, pp_pending_dst, pp_pending_meta, pp_count, num_comm_blocks);
369	        tiles_sent++;
370	    }
371	
372	    RsFlushPipeline(pingTile, pongTile, pp_pending_dst, pp_pending_meta, pp_count, hcclCtx, signal_base, my_rank);
373	    pipe_barrier(PIPE_ALL);
374	}
375	
376	// Transfer a contiguous sub-tile of rows from local reduced_output to a remote rank.
377	AICORE inline void AgTransferRows(
378	    __gm__ half* reduced_output, __gm__ CommDeviceContext* hcclCtx, const StrideDyn& tileStride, int r,
379	    uint64_t row_offset, int nrows)
380	{
381	    ShapeDyn subShape(1, 1, 1, nrows, G_BASE_N);
382	    Global srcG(reduced_output + row_offset, subShape, tileStride);
383	
384	    AgSubtileData subTile(nrows, G_BASE_N);
385	    TASSIGN(subTile, AG_SUBTILE_UB_OFFSET);
386	
387	    TLOAD(subTile, srcG);
388	    set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID2);
389	    wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID2);
390	
391	    __gm__ half* dst_ptr = CommRemotePtr(hcclCtx, reduced_output, r) + row_offset;
392	    Global dstG(dst_ptr, subShape, tileStride);
393	    TSTORE_IMPL<AgSubtileData, Global, pto::AtomicType::AtomicNone>(dstG, subTile);
394	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID2);
395	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID2);
396	}
397	
398	// ============================================================================
399	// Phase 2 helpers: map owner-local subtile ids back to the global reduced_output.
400	// A communication tile is logically split along M into fixed-height subtile rows.
401	// ============================================================================
402	AICORE inline int AgGetMyTileCount(int total_tiles, int my_rank, int nranks)
403	{
404	    const int safe_nranks = (nranks > 0) ? nranks : 1;
405	    if (safe_nranks == 1) {
406	        return total_tiles;
407	    }
408	    const int tiles_per_owner = (total_tiles + safe_nranks - 1) / safe_nranks;
409	    const int remainder = total_tiles % safe_nranks;
410	    return (my_rank < remainder || remainder == 0) ? tiles_per_owner : (total_tiles / safe_nranks);
411	}
412	
413	AICORE inline bool AgDecodeLocalSubtile(
414	    int local_subtile_id, int my_rank, int nranks, int total_tiles, uint64_t& row_offset)
415	{
416	    const int owner_local_tile = local_subtile_id / static_cast<int>(G_COMM_SUBTILES_PER_TILE);
417	    const int stripe_id = local_subtile_id % static_cast<int>(G_COMM_SUBTILES_PER_TILE);
418	    const int global_tile = my_rank + owner_local_tile * nranks;
419	    if (global_tile >= total_tiles) {
420	        return false;
421	    }
422	
423	    const uint32_t mi = global_tile / G_N_TILES;
424	    const uint32_t ni = global_tile % G_N_TILES;
425	    const uint64_t tile_base = (uint64_t)(mi * G_BASE_M) * G_N + ni * G_BASE_N;
426	    row_offset = tile_base + (uint64_t)stripe_id * G_COMM_SUB_M * G_N;
427	    return true;
428	}
429	
430	AICORE inline void AgTransferSubtileToAll(
431	    __gm__ half* reduced_output, __gm__ CommDeviceContext* hcclCtx, const StrideDyn& tileStride, int my_rank,
432	    int nranks, int total_tiles, int local_subtile_id)
433	{
434	    uint64_t row_offset = 0;
435	    if (!AgDecodeLocalSubtile(local_subtile_id, my_rank, nranks, total_tiles, row_offset)) {
436	        return;
437	    }
438	
439	    if (nranks <= 1) {
440	        return;
441	    }
442	
443	    // Rotate the first remote peer per subtile so comm blocks do not all hammer
444	    // the same destination first, which helps smooth out run-to-run hotspots.
445	    const int start_step = 1 + (local_subtile_id % (nranks - 1));
446	    for (int peer_offset = 0; peer_offset < nranks - 1; ++peer_offset) {
447	        const int logical_step = 1 + ((start_step - 1 + peer_offset) % (nranks - 1));
448	        const int r = (my_rank + logical_step) % nranks;
449	        AgTransferRows(reduced_output, hcclCtx, tileStride, r, row_offset, G_COMM_SUB_M);
450	    }
451	}
452	
453	// ============================================================================
454	// Phase 2: AllGather — owner-local subtile decomposition
455	//
456	// Each owner-local tile is split into G_COMM_SUBTILES_PER_TILE fixed subtile
457	// rows. AIV blocks partition the local subtile id range evenly and each task
458	// broadcasts one subtile to all remote ranks.
459	//
460	// This keeps the current "all owner-local data is gathered" semantics while
461	// introducing a subtile-granularity executor that later steps can drive from
462	// subtile-ready signals instead of a single global RS barrier.
463	// ============================================================================
464	AICORE inline void AllGatherPhase(
465	    __gm__ half* reduced_output, __gm__ CommDeviceContext* hcclCtx, int my_rank, int nranks, int comm_block_idx,
466	    int num_comm_blocks)
467	{
468	    const int total_tiles = G_NUM_TILES;
469	    const int my_tile_count = AgGetMyTileCount(total_tiles, my_rank, nranks);
470	    const int total_local_subtiles = my_tile_count * static_cast<int>(G_COMM_SUBTILES_PER_TILE);
471	
472	    if (total_local_subtiles <= 0 || nranks <= 1) {
473	        pipe_barrier(PIPE_ALL);
474	        return;
475	    }
476	
477	    StrideDyn tileStride(G_BASE_M * G_N, G_BASE_M * G_N, G_BASE_M * G_N, G_N, 1);
478	
479	    const int subtiles_per_block = (total_local_subtiles + num_comm_blocks - 1) / num_comm_blocks;
480	    int subtile_start = comm_block_idx * subtiles_per_block;

