494	// Phase 2 helpers: static AG work assignment plus subtile-ready probing.
495	// ============================================================================
496	struct AgAssignedState {
497	    uint16_t ids[G_SIGNAL_MAX_LOCAL_SUBTILES];
498	    uint8_t done[G_SIGNAL_MAX_LOCAL_SUBTILES];
499	    int count;
500	    int completed;
501	    int probe_cursor;
502	    int summary_slot;
503	    int summary_ack_count;
504	};
505	
506	AICORE inline void AgInitAssignedState(
507	    AgAssignedState& state, int total_local_subtiles, int comm_block_idx, int num_comm_blocks)
508	{
509	    state.count = 0;
510	    state.completed = 0;
511	    state.probe_cursor = 0;
512	    state.summary_slot = comm_block_idx;
513	    state.summary_ack_count = 0;
514	    // Start from (num_comm_blocks - 1 - comm_block_idx) to match the reversed
515	    // AgSummaryBlockForSubtile mapping. Stride stays num_comm_blocks.
516	    const int start_id = (num_comm_blocks > 0) ? (num_comm_blocks - 1 - comm_block_idx) : 0;
517	    for (int id = start_id; id < total_local_subtiles; id += num_comm_blocks) {
518	        if (id < 0)
519	            continue;
520	        state.ids[state.count] = static_cast<uint16_t>(id);
521	        state.done[state.count] = 0;
522	        state.count++;
523	    }
524	}
525	
526	AICORE inline bool AgAllDone(const AgAssignedState& state) { return state.completed >= state.count; }
527	
528	AICORE inline bool AgDrainReadyAssignedSubtiles(
529	    __gm__ half* reduced_output, __gm__ int32_t* signal_base, __gm__ CommDeviceContext* hcclCtx,
530	    const StrideDyn& tileStride, int my_rank, int nranks, int total_tiles, AgAssignedState& state)
531	{
532	    if (AgAllDone(state) || nranks <= 1 || state.count <= 0) {
533	        return false;
534	    }
535	
536	    bool acquired = false;
537	    bool drained_any = false;
538	    int last_idx = state.probe_cursor;
539	
540	    for (int i = 0; i < state.count; ++i) {
541	        const int idx = (state.probe_cursor + i) % state.count;
542	        if (state.done[idx]) {
543	            continue;
544	        }
545	
546	        const int local_subtile_id = static_cast<int>(state.ids[idx]);
547	        pto::comm::Signal sig(signal_base + G_SIGNAL_SUBTILE_READY_OFFSET + local_subtile_id);
548	        if (!pto::comm::TTEST(sig, nranks, pto::comm::WaitCmp::GE)) {
549	            continue;
550	        }
551	
552	        if (!acquired) {
553	            // One acquire fence is enough to consume all currently-ready subtiles
554	            // published before this drain pass.
555	            pipe_barrier(PIPE_ALL);
556	            dsb(DSB_DDR);
557	            acquired = true;
558	        }
559	        AgTransferSubtileToAll(reduced_output, hcclCtx, tileStride, my_rank, nranks, total_tiles, local_subtile_id);
560	        state.done[idx] = 1;
561	        state.completed++;
562	        state.summary_ack_count++;
563	        last_idx = idx;
564	        drained_any = true;
565	    }
566	
567	    if (drained_any) {
568	        state.probe_cursor = (state.count > 0) ? ((last_idx + 1) % state.count) : 0;
569	    }
570	    return drained_any;
571	}
572	
573	AICORE inline void AgWaitAssignedSummary(__gm__ int32_t* signal_base, int nranks, AgAssignedState& state)
574	{
575	    if (AgAllDone(state) || state.count <= 0) {
576	        return;
577	    }
578	
579	    pto::comm::Signal sig(AgSummarySlotPtr(signal_base, state.summary_slot));
580	    pto::comm::TWAIT(sig, state.summary_ack_count + 1, pto::comm::WaitCmp::GE);
581	}
