653	// Mixed subtile pipeline:
654	//   RS produces owner-local subtile-ready counters
655	//   AG consumes ready subtile counters without a global RS→AG barrier
656	// ============================================================================
657	AICORE inline void GemmCommAllImpl(
658	    __gm__ half* gemm_output, __gm__ half* reduced_output, __gm__ int32_t* signal_matrix,
659	    __gm__ MultiBlockQueueSet* queue_set, __gm__ CommDeviceContext* hcclCtx, int rank, int nranks,
660	    int num_compute_blocks, int comm_block_idx, int num_comm_blocks)
661	{
662	    int my_rank = hcclCtx->rankId;
663	    const int total_tiles = G_NUM_TILES;
664	    const int my_tile_count = AgGetMyTileCount(total_tiles, my_rank, nranks);
665	    const int total_local_subtiles = my_tile_count * static_cast<int>(G_COMM_SUBTILES_PER_TILE);
666	
667	    volatile __gm__ MultiBlockQueueSet* qset = (volatile __gm__ MultiBlockQueueSet*)queue_set;
668	    ShapeDyn subtileShape(1, 1, 1, G_COMM_SUB_M, G_BASE_N);
669	    StrideDyn subtileStride(G_BASE_M * G_N, G_BASE_M * G_N, G_BASE_M * G_N, G_N, 1);
670	
671	    RsSubtileData pingTile(G_COMM_SUB_M, G_BASE_N);
672	    RsSubtileData pongTile(G_COMM_SUB_M, G_BASE_N);
673	    TASSIGN(pingTile, 0x0);
674	    TASSIGN(pongTile, RS_SUBTILE_UB_BYTES);
675	
676	    RsPipelineState rsState(
677	        gemm_output, subtileShape, subtileStride, comm_block_idx, num_compute_blocks, num_comm_blocks);
678	    AgAssignedState agState;
679	    AgInitAssignedState(agState, total_local_subtiles, comm_block_idx, num_comm_blocks);
680	
681	    bool rs_done = (rsState.tiles_sent >= rsState.my_expected_tiles);
682	    bool ag_done = AgAllDone(agState) || nranks <= 1;
683	
684	    while (!rs_done || !ag_done) {
685	        bool did_work = false;
686	
687	        if (!rs_done) {
688	            did_work = GemmCommTryRs(
689	                gemm_output, reduced_output, signal_matrix, qset, hcclCtx, my_rank, nranks, subtileShape, subtileStride,
690	                pingTile, pongTile, rsState, num_comm_blocks, rs_done);
691	        }
692	
693	        if (!ag_done) {
694	            did_work = did_work || GemmCommTryAg(
695	                                       reduced_output, signal_matrix, hcclCtx, subtileStride, my_rank, nranks,
696	                                       total_tiles, agState, ag_done);
697	        }
698	
699	        if (!did_work) {
700	            GemmCommWaitForWork(qset, signal_matrix, nranks, rsState, rs_done, ag_done, agState);
701	        }
702	    }
703	
704	    pipe_barrier(PIPE_ALL);
705	}
